        public static IReadOnlyList<GospelOpeningPage> Opening { get; }=Array.AsReadOnly(new[] {
            new GospelOpeningPage("한 생애, 말씀을 따라","탄생에서 시작된 이야기","예수님의 생애를 복음서의 기록과 함께 따라갑니다. 이번 첫 장은 베들레헴의 탄생을 되짚고 열두 살의 성전 방문으로 이어집니다. 대화는 본문을 바탕으로 한 학습용 극화이며, 아래에 표시되는 성경 직접 인용과 구분됩니다.","누가복음 2장"),
            new GospelOpeningPage("베들레헴의 아기","구유에 뉘인 예수님","요셉과 마리아는 호적하러 베들레헴에 갔습니다. 그곳에서 아기가 태어나 강보에 싸여 구유에 뉘었습니다. 목자들에게 큰 기쁨의 소식이 전해졌고, 그들은 찾아가 듣고 본 일을 알렸습니다.","누가복음 2:1–20"),
            new GospelOpeningPage("이름과 성전의 만남","이름을 예수라 하니","아기의 이름은 예수라 하였습니다. 부모는 율법을 따라 아기를 데리고 성전에 갔고, 시므온과 안나가 그곳에서 아기를 만났습니다. 도중의 대화에서 이 기록들을 한 장씩 찾아 읽게 됩니다.","누가복음 2:21–38"),
            new GospelOpeningPage("나사렛에서 자라시다","성경이 전하는 어린 시절","가족은 나사렛으로 돌아갔습니다. 누가는 아기가 자라며 강하여지고 지혜가 충족하며 하나님의 은혜가 그 위에 있었다고 전합니다. 모든 어린 시절이 기록된 것은 아니며, 이 여정은 남아 있는 본문을 따라갑니다.","누가복음 2:39–40"),
            new GospelOpeningPage("지금, 열두 살","유월절의 예루살렘","이제 여러분이 움직이는 인물은 열두 살 예수님입니다. 유월절에 부모와 예루살렘에 올라온 때입니다. 올리브 뜰의 만남에서 앞선 기록을 되짚은 뒤, 선생들과 부모를 만나는 성전 이야기를 따라갑니다.","누가복음 2:41–52"),
            new GospelOpeningPage("말씀을 모으는 여정","걸으며 만나고, 읽으며 기억하다","빛나는 장소로 걸어가 사람과 대화하세요. 대화를 끝까지 읽으면 성경 말씀이 도감에 들어옵니다. 위에는 학습 대화, 아래에는 정확한 성경 본문이 표시됩니다. 가방의 등잔을 켜고, 책 아이콘에서 모은 말씀을 다시 읽을 수 있습니다.","첫 장 · 보통 읽기와 탐색 약 10–15분")
        });
